-- Stage additions are separate from immutable submitted payloads; canonical approval events own signatures.
CREATE TABLE dqa_private.template_stage_operation_fields(
 tenant_id uuid NOT NULL,operation_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('WORKFLOW','HUMAN')),actor uuid NOT NULL,
 command_hash text NOT NULL,fields_hash text NOT NULL,request_id uuid NOT NULL,document_id uuid NOT NULL,schedule_id uuid,stage text NOT NULL,fields jsonb NOT NULL,
 PRIMARY KEY(tenant_id,kind,operation_id),FOREIGN KEY(tenant_id,document_id,request_id) REFERENCES dqa_business.request_document_versions(tenant_id,id,request_id) ON DELETE CASCADE);
CREATE TABLE dqa_private.request_template_stage_entries(
 tenant_id uuid NOT NULL,event_id uuid NOT NULL,request_id uuid NOT NULL,document_id uuid NOT NULL,stage text NOT NULL,schedule_id uuid,fields jsonb NOT NULL,
 PRIMARY KEY(tenant_id,event_id),FOREIGN KEY(tenant_id,event_id) REFERENCES dqa_business.approval_events(tenant_id,id) ON DELETE CASCADE,
 FOREIGN KEY(tenant_id,document_id,request_id) REFERENCES dqa_business.request_document_versions(tenant_id,id,request_id) ON DELETE CASCADE);
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['template_stage_operation_fields','request_template_stage_entries'] LOOP
 EXECUTE format('ALTER TABLE dqa_private.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON dqa_private.%I FROM PUBLIC,anon,authenticated,service_role',t);
 END LOOP;END $$;
