CREATE FUNCTION dqa_private.template_stage_required(p_stage text,p_mapping jsonb) RETURNS text[] LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE keys text[];dep record;
BEGIN
 SELECT coalesce(array_agg(DISTINCT f->>'key'),'{}') INTO keys FROM jsonb_array_elements(dqa_private.template_stage_schema()->'fields') f WHERE f->>'key'<>'' AND (f->>'stage'=p_stage OR p_stage='LAB_COMPLETE' AND f->>'stage'='LAB_RECEIVE' AND f->>'key' IN('executionAbnormal','abnormalDescription')) AND EXISTS(SELECT 1 FROM jsonb_array_elements(p_mapping) m WHERE m->>'field'=f->>'id');
 FOR dep IN SELECT * FROM (VALUES('permitOther','permitTypes'),('outsourceExpectedDate','outsourced'),('resourcesExpectedDate','resourcesReady'),('fixturesImprovedDate','fixturesReady'),('operationImprovedDate','operationFamiliar'),('abnormalDescription','executionAbnormal')) v(k,d) LOOP IF dep.k=ANY(keys) AND NOT dep.d=ANY(keys) THEN keys:=array_append(keys,dep.d);END IF;END LOOP;
 RETURN keys;
END $$;
CREATE FUNCTION dqa_private.validate_template_stage_fields(p_stage text,p_fields jsonb,p_required text[] DEFAULT '{}') RETURNS void LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE defs jsonb:=coalesce(dqa_private.template_stage_schema()->'inputs'->p_stage,'[]');item jsonb;v jsonb;k text;typ text;need boolean;dt date;i integer;
BEGIN
 IF jsonb_typeof(p_fields) IS DISTINCT FROM 'object' OR octet_length(p_fields::text)>12000 THEN RAISE EXCEPTION 'TEMPLATE_STAGE_FIELDS_INVALID';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_fields) x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(defs) d WHERE d->>0=x)) THEN RAISE EXCEPTION 'TEMPLATE_STAGE_FIELDS_INVALID';END IF;
 FOR item IN SELECT jsonb_array_elements(defs) LOOP
  k:=item->>0;typ:=item->>2;v:=p_fields->k;
  IF v IS NOT NULL THEN
   IF typ='multi' THEN
    IF jsonb_typeof(v) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'TEMPLATE_STAGE_FIELDS_INVALID';END IF;
    IF jsonb_array_length(v)>3 OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(v) x)<>jsonb_array_length(v) OR EXISTS(SELECT 1 FROM jsonb_array_elements(v) x WHERE jsonb_typeof(x)<>'string' OR NOT (item->3 @> jsonb_build_array(x))) THEN RAISE EXCEPTION 'TEMPLATE_STAGE_FIELDS_INVALID';END IF;
   ELSIF typ IN('choice','optionalChoice','pendingChoice') THEN
    IF jsonb_typeof(v) IS DISTINCT FROM 'string' OR NOT(v#>>'{}'=ANY(CASE typ WHEN 'optionalChoice' THEN ARRAY['yes','no','not_applicable'] WHEN 'pendingChoice' THEN ARRAY['yes','no','pending'] ELSE ARRAY['yes','no'] END)) THEN RAISE EXCEPTION 'TEMPLATE_STAGE_FIELDS_INVALID';END IF;
   ELSIF typ='number' THEN
    IF jsonb_typeof(v) IS DISTINCT FROM 'number' OR v::text !~ '^(0|[1-9][0-9]{0,5})$' THEN RAISE EXCEPTION 'TEMPLATE_STAGE_FIELDS_INVALID';END IF;
   ELSE
    IF jsonb_typeof(v) IS DISTINCT FROM 'string' OR length(v#>>'{}')>1000 THEN RAISE EXCEPTION 'TEMPLATE_STAGE_FIELDS_INVALID';END IF;
    IF typ='date' THEN BEGIN
     IF v#>>'{}' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'TEMPLATE_STAGE_FIELDS_INVALID';END IF;
     dt:=(v#>>'{}')::date;IF to_char(dt,'YYYY-MM-DD')<>v#>>'{}' THEN RAISE EXCEPTION 'TEMPLATE_STAGE_FIELDS_INVALID';END IF;
     EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'TEMPLATE_STAGE_FIELDS_INVALID';END;END IF;
   END IF;
  END IF;
  need:=k=ANY(p_required);
  IF k='permitOther' THEN need:=need AND coalesce(p_fields->'permitTypes' @> '["other"]',false);
  ELSIF k='outsourceExpectedDate' THEN need:=need AND p_fields->>'outsourced'='yes';
  ELSIF k='resourcesExpectedDate' THEN need:=need AND p_fields->>'resourcesReady'='no';
  ELSIF k='fixturesImprovedDate' THEN need:=need AND p_fields->>'fixturesReady'='no';
  ELSIF k='operationImprovedDate' THEN need:=need AND p_fields->>'operationFamiliar'='no';
  ELSIF k='abnormalDescription' THEN need:=need AND p_fields->>'executionAbnormal'='yes';END IF;
  IF need AND (v IS NULL OR v='[]'::jsonb OR coalesce(length(btrim(v#>>'{}')),0)=0) THEN RAISE EXCEPTION 'TEMPLATE_STAGE_FIELDS_REQUIRED';END IF;
 END LOOP;
 IF p_fields->'permitTypes' @> '["other"]' AND coalesce(length(btrim(p_fields->>'permitOther')),0)=0 OR p_fields->>'executionAbnormal'='yes' AND coalesce(length(btrim(p_fields->>'abnormalDescription')),0)=0 THEN RAISE EXCEPTION 'TEMPLATE_STAGE_FIELDS_REQUIRED';END IF;
 FOR i IN 1..3 LOOP IF p_fields->>('equipmentEnd'||i)<p_fields->>('equipmentStart'||i) THEN RAISE EXCEPTION 'TEMPLATE_STAGE_FIELDS_INVALID';END IF;END LOOP;
END $$;
-- Prepare receipts bind the exact input, current document and schedule. Base RPCs cannot bypass mapped requirements.
CREATE FUNCTION dqa_private.bind_template_stage_operation(p_tenant uuid,p_operation uuid,p_kind text,p_command jsonb,p_fields jsonb,p_prepare boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE q dqa_business.requests;old dqa_private.template_stage_operation_fields;st text;sid uuid;fp text;cfp text;req text[];mp jsonb;
BEGIN
 SELECT * INTO q FROM dqa_business.requests WHERE tenant_id=p_tenant AND id=(p_command->>'request_id')::uuid;
 IF q.id IS NULL OR NOT dqa_private.can_read_request(p_tenant,q.id) THEN RAISE EXCEPTION 'DOCUMENT_MAPPING_ACCESS_DENIED';END IF;
 IF p_kind='WORKFLOW' AND p_command->>'action'='LMS_APPROVE' THEN st:='LMS_'||(q.request_review_level+1);
 ELSIF p_kind='HUMAN' AND p_command->>'action' IN('RECEIVE','COMPLETE') THEN st:=CASE p_command->>'action' WHEN 'RECEIVE' THEN 'LAB_RECEIVE' ELSE 'LAB_COMPLETE' END;
 ELSE RAISE EXCEPTION 'TEMPLATE_STAGE_FIELDS_INVALID';END IF;
 fp:=encode(sha256(convert_to(p_fields::text,'UTF8')),'hex');cfp:=encode(sha256(convert_to(p_command::text,'UTF8')),'hex');
 SELECT * INTO old FROM dqa_private.template_stage_operation_fields WHERE tenant_id=p_tenant AND kind=p_kind AND operation_id=p_operation;
 IF FOUND THEN
  IF old.actor<>auth.uid() OR old.command_hash<>cfp OR old.fields_hash IS DISTINCT FROM fp THEN RAISE EXCEPTION 'TEMPLATE_STAGE_OPERATION_CONFLICT';END IF;
  RETURN;
 END IF;
 IF NOT p_prepare THEN RAISE EXCEPTION 'TEMPLATE_STAGE_OPERATION_CONFLICT';END IF;
 IF q.request_document_version_id IS NULL THEN RAISE EXCEPTION 'WORKFLOW_DOCUMENT_REQUIRED';END IF;
 IF st LIKE 'LAB_%' THEN SELECT id INTO sid FROM dqa_business.schedules WHERE tenant_id=p_tenant AND request_id=q.id AND status NOT IN('DRAFT','CANCELLED');END IF;
 SELECT request_mapping INTO mp FROM dqa_private.mapped_document_pins WHERE tenant_id=p_tenant AND document_id=q.request_document_version_id;
 req:=dqa_private.template_stage_required(st,coalesce(mp,'[]'));PERFORM dqa_private.validate_template_stage_fields(st,p_fields,req);
 INSERT INTO dqa_private.template_stage_operation_fields VALUES(p_tenant,p_operation,p_kind,auth.uid(),cfp,fp,q.id,q.request_document_version_id,sid,st,p_fields);
END $$;
CREATE FUNCTION dqa_private.capture_template_stage_entry() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE receipt dqa_private.template_stage_operation_fields;mp jsonb;sid uuid;vals jsonb:='{}';
BEGIN
 IF NEW.decision<>'APPROVE' OR NEW.stage NOT IN('REQUEST_MANAGER','LMS_1','LMS_2','LAB_RECEIVE','LAB_COMPLETE') OR NEW.request_document_version_id IS NULL THEN RETURN NEW;END IF;
 IF NEW.stage LIKE 'LAB_%' THEN SELECT id INTO sid FROM dqa_business.schedules WHERE tenant_id=NEW.tenant_id AND request_id=NEW.request_id AND status NOT IN('DRAFT','CANCELLED');END IF;
 SELECT * INTO receipt FROM dqa_private.template_stage_operation_fields WHERE tenant_id=NEW.tenant_id AND operation_id=NEW.operation_id AND kind=CASE WHEN NEW.stage LIKE 'LAB_%' THEN 'HUMAN' ELSE 'WORKFLOW' END;
 IF FOUND THEN
  IF receipt.actor IS DISTINCT FROM auth.uid() OR receipt.request_id<>NEW.request_id OR receipt.document_id<>NEW.request_document_version_id OR receipt.stage<>NEW.stage OR receipt.schedule_id IS DISTINCT FROM sid THEN RAISE EXCEPTION 'TEMPLATE_STAGE_OPERATION_CONFLICT';END IF;
  vals:=receipt.fields;
 END IF;
 SELECT request_mapping INTO mp FROM dqa_private.mapped_document_pins WHERE tenant_id=NEW.tenant_id AND document_id=NEW.request_document_version_id;
 PERFORM dqa_private.validate_template_stage_fields(NEW.stage,vals,dqa_private.template_stage_required(NEW.stage,coalesce(mp,'[]')));
 INSERT INTO dqa_private.request_template_stage_entries VALUES(NEW.tenant_id,NEW.id,NEW.request_id,NEW.request_document_version_id,NEW.stage,sid,vals);
 RETURN NEW;
END $$;
CREATE TRIGGER capture_template_stage AFTER INSERT ON dqa_business.approval_events FOR EACH ROW EXECUTE FUNCTION dqa_private.capture_template_stage_entry();
CREATE FUNCTION dqa_business.prepare_request_template_operation(p_tenant uuid,p_operation uuid,p_command jsonb,p_fields jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 result:=dqa_business.prepare_request_operation(p_tenant,p_operation,p_command);
 PERFORM dqa_private.bind_template_stage_operation(p_tenant,p_operation,'WORKFLOW',p_command,p_fields,true);
 RETURN result;
END $$;
CREATE FUNCTION dqa_business.execute_request_template_operation(p_tenant uuid,p_operation uuid,p_command jsonb,p_fields jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 PERFORM dqa_private.bind_template_stage_operation(p_tenant,p_operation,'WORKFLOW',p_command,p_fields,false);
 result:=dqa_business.execute_request_operation(p_tenant,p_operation,p_command);
 RETURN result;
END $$;
CREATE FUNCTION dqa_business.prepare_human_template_operation(p_tenant uuid,p_operation uuid,p_command jsonb,p_fields jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 result:=dqa_business.prepare_human_operation(p_tenant,p_operation,p_command);
 PERFORM dqa_private.bind_template_stage_operation(p_tenant,p_operation,'HUMAN',p_command,p_fields,true);
 RETURN result;
END $$;
CREATE FUNCTION dqa_business.execute_human_template_operation(p_tenant uuid,p_operation uuid,p_command jsonb,p_fields jsonb,p_attestation text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 PERFORM dqa_private.bind_template_stage_operation(p_tenant,p_operation,'HUMAN',p_command,p_fields,false);
 result:=dqa_business.execute_human_operation(p_tenant,p_operation,p_command,p_attestation);
 RETURN result;
END $$;
CREATE FUNCTION dqa_private.template_stage_context(p_tenant uuid,p_document uuid,p_signatures boolean DEFAULT false) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT coalesce(jsonb_object_agg(x.stage,x.data),'{}') FROM (
 SELECT DISTINCT ON(e.stage) e.stage,jsonb_build_object('fields',coalesce(t.fields,'{}'),'actor',e.actor_label,'at',e.created_at)||CASE WHEN p_signatures THEN jsonb_build_object('signature_data',s.signature_data,'signature_sha256',s.signature_sha256) ELSE '{}' END data
 FROM dqa_business.approval_events e JOIN dqa_business.request_signatures s ON s.tenant_id=e.tenant_id AND s.approval_event_id=e.id AND s.document_version_id=e.request_document_version_id
 LEFT JOIN dqa_private.request_template_stage_entries t ON t.tenant_id=e.tenant_id AND t.event_id=e.id
 WHERE e.tenant_id=p_tenant AND e.request_document_version_id=p_document AND (e.stage='REQUESTER' AND e.decision='SUBMIT' OR e.stage IN('REQUEST_MANAGER','LMS_1','LMS_2','LAB_RECEIVE','LAB_COMPLETE') AND e.decision='APPROVE')
 AND (e.stage NOT LIKE 'LAB_%' OR t.schedule_id=(SELECT id FROM dqa_business.schedules WHERE tenant_id=p_tenant AND request_id=e.request_id AND status NOT IN('DRAFT','CANCELLED')))
 ORDER BY e.stage,e.created_at DESC,e.id DESC)x
$$;
CREATE FUNCTION dqa_business.document_mapping_stage_context(p_tenant uuid,p_document uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE q dqa_business.requests;mp jsonb;
BEGIN
 SELECT * INTO q FROM dqa_business.requests WHERE tenant_id=p_tenant AND request_document_version_id=p_document;
 IF q.id IS NULL OR NOT dqa_private.can(p_tenant) OR NOT dqa_private.can_read_request(p_tenant,q.id) OR NOT dqa_private.case_row_active(p_tenant,'requests',q.id) THEN RAISE EXCEPTION 'DOCUMENT_MAPPING_ACCESS_DENIED';END IF;
 SELECT request_mapping INTO mp FROM dqa_private.mapped_document_pins WHERE tenant_id=p_tenant AND document_id=p_document;
 RETURN jsonb_build_object('document_id',p_document,'mapping',coalesce(mp,'[]'),'stages',dqa_private.template_stage_context(p_tenant,p_document));
END $$;
CREATE OR REPLACE FUNCTION dqa_business.save_document_mapping(p_tenant uuid,p_operation uuid,p_kind text,p_file uuid,p_revision integer,p_sha256 text,p_mapping jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE s jsonb;fp text;op dqa_private.document_mapping_operations;old dqa_private.document_cell_mappings;result jsonb;
BEGIN
 IF NOT dqa_private.is_admin(p_tenant) THEN RAISE EXCEPTION 'DOCUMENT_MAPPING_ACCESS_DENIED';END IF;
 IF p_operation IS NULL OR p_file IS NULL OR p_kind NOT IN('REQUEST','REPORT') OR p_kind IS NULL OR p_revision IS NULL OR p_revision<0 OR p_sha256 IS NULL THEN RAISE EXCEPTION 'DOCUMENT_MAPPING_INVALID';END IF;
 IF jsonb_typeof(p_mapping) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'DOCUMENT_MAPPING_INVALID';END IF;
 IF jsonb_array_length(p_mapping) NOT BETWEEN 1 AND 224 OR octet_length(p_mapping::text)>60000 THEN RAISE EXCEPTION 'DOCUMENT_MAPPING_INVALID';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_mapping) r WHERE jsonb_typeof(r)<>'object' OR (r-'field'-'sheet'-'cell')<>'{}' OR jsonb_typeof(r->'field') IS DISTINCT FROM 'string' OR jsonb_typeof(r->'sheet') IS DISTINCT FROM 'string' OR length(r->>'sheet') NOT BETWEEN 1 AND 31 OR jsonb_typeof(r->'cell') IS DISTINCT FROM 'string' OR r->>'cell' !~ '^([A-Z]|A[A-V])([1-9][0-9]{0,2}|1[0-9]{3}|2000)$' OR r->>'field' NOT IN('id','productCode','productType','customer','customerPartNo','dueDate','quantity','department','requester','supervisor','priority','project','testItems','specification','judgementRequired','judgementCriteria','purpose','purposeOther','sampleSource','sampleSourceOther','productVersion','pcbaVersion','softwareVersion','manufactureDate','sampleDescription','notes','sourceInHouse','sourceOverseas','sourceCustomer','sourceSupplier','sourceCompetitor','judgementRequiredCheck','judgementNotRequiredCheck','purposeNewProduct','purposeEV','purposeReproduction','purposeOtherSelected','purposeDesignChange','purposeDV','purposePeriodic','purposeMassProduct','purposePV','purposeOtherContent','sourceInHouseContent','sourceOverseasContent','sourceCustomerContent','sourceSupplierContent','sourceCompetitorContent','lms1PermitNewProductCheck','lms1PermitDesignChangeCheck','lms1PermitOtherCheck','lms1PermitOtherContent','lms1AllowedYesCheck','lms1AllowedNoCheck','lms1CriteriaClearYesCheck','lms1CriteriaClearNoCheck','lms1OutsourcedYesCheck','lms1OutsourcedNoCheck','lms1ResourcesReadyYesCheck','lms1ResourcesReadyNoCheck','lms1OutsourceExpectedDate','lms1OutsourceExpectedDateYear','lms1OutsourceExpectedDateMonth','lms1OutsourceExpectedDateDay','lms1ResourcesExpectedDate','lms1ResourcesExpectedDateYear','lms1ResourcesExpectedDateMonth','lms1ResourcesExpectedDateDay','lms1SampleCode','lms1Equipment1','lms1EquipmentStart1','lms1EquipmentStart1Year','lms1EquipmentStart1Month','lms1EquipmentStart1Day','lms1EquipmentEnd1','lms1EquipmentEnd1Year','lms1EquipmentEnd1Month','lms1EquipmentEnd1Day','lms1Equipment2','lms1EquipmentStart2','lms1EquipmentStart2Year','lms1EquipmentStart2Month','lms1EquipmentStart2Day','lms1EquipmentEnd2','lms1EquipmentEnd2Year','lms1EquipmentEnd2Month','lms1EquipmentEnd2Day','lms1Equipment3','lms1EquipmentStart3','lms1EquipmentStart3Year','lms1EquipmentStart3Month','lms1EquipmentStart3Day','lms1EquipmentEnd3','lms1EquipmentEnd3Year','lms1EquipmentEnd3Month','lms1EquipmentEnd3Day','lms1PlannedOperator','lms1PlannedStartDate','lms1PlannedStartDateYear','lms1PlannedStartDateMonth','lms1PlannedStartDateDay','lms1ReportDueDate','lms1ReportDueDateYear','lms1ReportDueDateMonth','lms1ReportDueDateDay','labSampleCorrectYesCheck','labSampleCorrectNoCheck','labSampleQuantity','labSampleReceivedDate','labSampleReceivedDateYear','labSampleReceivedDateMonth','labSampleReceivedDateDay','labFixturesReadyYesCheck','labFixturesReadyNoCheck','labFixturesReadyNotApplicableCheck','labFixturesImprovedDate','labFixturesImprovedDateYear','labFixturesImprovedDateMonth','labFixturesImprovedDateDay','labOperationFamiliarYesCheck','labOperationFamiliarNoCheck','labOperationImprovedDate','labOperationImprovedDateYear','labOperationImprovedDateMonth','labOperationImprovedDateDay','labOutsourceBookedYesCheck','labOutsourceBookedNoCheck','labOutsourceBookedNotApplicableCheck','labOutsourceCompletedDate','labOutsourceCompletedDateYear','labOutsourceCompletedDateMonth','labOutsourceCompletedDateDay','labExecutionAbnormalYesCheck','labExecutionAbnormalNoCheck','labAbnormalDescription','requesterSignature','requesterName','requesterSignedDate','requesterSignedYear','requesterSignedMonth','requesterSignedDay','requestManagerSignature','requestManagerName','requestManagerSignedDate','requestManagerSignedYear','requestManagerSignedMonth','requestManagerSignedDay','lms1Signature','lms1Name','lms1SignedDate','lms1SignedYear','lms1SignedMonth','lms1SignedDay','lms2Signature','lms2Name','lms2SignedDate','lms2SignedYear','lms2SignedMonth','lms2SignedDay','labReceiptSignature','labReceiptName','labReceiptSignedDate','labReceiptSignedYear','labReceiptSignedMonth','labReceiptSignedDay','labCompletionSignature','labCompletionName','labCompletionSignedDate','labCompletionSignedYear','labCompletionSignedMonth','labCompletionSignedDay')) OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_mapping) r GROUP BY r->>'sheet',r->>'cell' HAVING count(*)>1) THEN RAISE EXCEPTION 'DOCUMENT_MAPPING_INVALID';END IF;
 IF p_kind='REPORT' AND EXISTS(SELECT 1 FROM jsonb_array_elements(p_mapping) r JOIN jsonb_array_elements(dqa_private.template_stage_schema()->'fields') f ON f->>'id'=r->>'field') THEN RAISE EXCEPTION 'DOCUMENT_MAPPING_INVALID';END IF;
 fp:=encode(sha256(convert_to(jsonb_build_array(p_kind,p_file,p_revision,p_sha256,p_mapping)::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('mapping-op:'||p_tenant||':'||p_operation,0));SELECT * INTO op FROM dqa_private.document_mapping_operations WHERE tenant_id=p_tenant AND id=p_operation;
 IF FOUND THEN IF op.actor<>auth.uid() OR op.fingerprint<>fp THEN RAISE EXCEPTION 'DOCUMENT_MAPPING_CONFLICT';END IF;RETURN op.result;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('document-mapping:'||p_tenant,0));s:=dqa_business.document_mapping_source(p_tenant,p_kind,p_file);
 IF s->>'sha256'<>p_sha256 THEN RAISE EXCEPTION 'DOCUMENT_MAPPING_CONFLICT';END IF;
 SELECT * INTO old FROM dqa_private.document_cell_mappings WHERE tenant_id=p_tenant AND kind=p_kind AND file_id=p_file;
 IF coalesce(old.revision,0)<>p_revision THEN RAISE EXCEPTION 'DOCUMENT_MAPPING_CONFLICT';END IF;
 INSERT INTO dqa_private.document_cell_mappings(tenant_id,kind,file_id,sha256,revision,mapping) VALUES(p_tenant,p_kind,p_file,p_sha256,1,p_mapping) ON CONFLICT(tenant_id,kind,file_id) DO UPDATE SET mapping=p_mapping,revision=dqa_private.document_cell_mappings.revision+1;
 result:=jsonb_build_object('id',p_operation,'state','SAVED','revision',coalesce(old.revision,0)+1);INSERT INTO dqa_private.document_mapping_operations VALUES(p_tenant,p_operation,auth.uid(),fp,result);
 INSERT INTO dqa_business.audit_events(tenant_id,actor_auth_user_id,database_role,table_name,record_id,operation,changed_columns) VALUES(p_tenant,auth.uid(),current_user,'document_cell_mappings',p_file,'UPDATE',ARRAY['mapping','revision']);RETURN result;
END $$;
CREATE OR REPLACE FUNCTION dqa_business.document_mapping_case(p_tenant uuid,p_kind text,p_document uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE pin dqa_private.mapped_document_pins;r jsonb;q dqa_business.requests;
BEGIN
 IF p_kind NOT IN('REQUEST','REPORT') OR p_kind IS NULL THEN RAISE EXCEPTION 'DOCUMENT_MAPPING_INVALID';END IF;
 SELECT * INTO q FROM dqa_business.requests WHERE tenant_id=p_tenant AND request_document_version_id=p_document;
 IF q.id IS NULL OR NOT dqa_private.can(p_tenant) OR NOT dqa_private.can_read_request(p_tenant,q.id) OR NOT dqa_private.case_row_active(p_tenant,'requests',q.id) THEN RAISE EXCEPTION 'DOCUMENT_MAPPING_ACCESS_DENIED';END IF;
 SELECT * INTO pin FROM dqa_private.mapped_document_pins WHERE tenant_id=p_tenant AND document_id=p_document;
 IF p_kind='REPORT' THEN
  r:=dqa_business.request_trial_template_file(p_tenant,p_document);IF r->>'has_template'='false' THEN RETURN r;END IF;
  IF pin.document_id IS NULL OR jsonb_array_length(pin.report_mapping)=0 THEN RAISE EXCEPTION 'DOCUMENT_MAPPING_REQUIRED';END IF;
  r:=r||jsonb_build_object('mapping',pin.report_mapping);
 ELSE
  IF pin.request_file_id IS NULL THEN RETURN jsonb_build_object('has_template',false);END IF;
  r:=jsonb_build_object('has_template',true,'id',pin.request_file_id,'document_id',p_document,'name',pin.request_name,'sha256',pin.request_sha256,'byteLength',octet_length(pin.request_content),'content',replace(encode(pin.request_content,'base64'),E'\n',''),'mapping',pin.request_mapping);
 END IF;
 RETURN r||CASE WHEN p_kind='REQUEST' THEN jsonb_build_object('stages',dqa_private.template_stage_context(p_tenant,p_document,true)) ELSE '{}' END||jsonb_build_object('kind',p_kind,'request_code',q.legacy_id,'payload',pin.payload,'department',pin.department,'execution_kind',pin.execution_kind);
END $$;
DO $$ DECLARE f regprocedure;BEGIN
 FOR f IN SELECT p.oid::regprocedure FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='dqa_private' AND p.proname IN('template_stage_schema','template_stage_required','validate_template_stage_fields','bind_template_stage_operation','capture_template_stage_entry','template_stage_context') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,service_role',f);END LOOP;
 FOR f IN SELECT p.oid::regprocedure FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='dqa_business' AND p.proname IN('prepare_request_template_operation','execute_request_template_operation','prepare_human_template_operation','execute_human_template_operation','document_mapping_stage_context') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,service_role',f);EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',f);END LOOP;
END $$;
